head.script:
scwin.screenId = "jldfil35700";

///////// 1. 변수 및 선언 영역 /////////

scwin.tbh_labels = ["계산기","영수증 발급"];
scwin.tbh_defaultIndex = 0;

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 탭 선택 초기화(init_tab)를 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        scwin.init_tab(); // 1) 탭 선택 초기화 (진입 파라미터 tab > 기본 탭)
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35700.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////

// 탭 전환 시 breadcrumb 리프를 선택 탭 라벨로 갱신한다.
//   onchange 는 tabControl 이 제공하는 사용자 이벤트다.
/**
 * @event
 * @name tbh_tabs_onchange
 * @description 탭 전환 시 breadcrumb 리프 텍스트를 선택된 탭 라벨로 갱신한다.
 * @returns {void}
 * @hidden N
 * @example (tbh_tabs ev:onchange 바인딩으로 자동 호출)
 */
scwin.tbh_tabs_onchange = function () {
    const tc = $c.util.getComponent('tbh_tabs');
    if (tc && tc.getSelectedTabIndex) { scwin.tbh_setLeaf(tc.getSelectedTabIndex()); }
};

///////// 4. 서브미션 콜백 영역 /////////

///////// 5. 일반/업무 함수 영역 /////////

// 탭 선택 = 진입 파라미터(tab) > 기본 탭. onpageload 는 엔진 초기화 뒤라 이 시점의 대입이 산다.
/**
 * @method
 * @name init_tab
 * @description 진입 파라미터(tab)가 있으면 해당 인덱스로, 없으면 기본 탭(tbh_defaultIndex)으로 탭을 선택하고 breadcrumb 리프를 갱신한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_tab();
 */
scwin.init_tab = function () {
    let idx = scwin.tbh_defaultIndex;
    const pd = $c.data.getParameter();
    if (pd && pd.tab !== undefined) { idx = Number(pd.tab); }
    const tc = $c.util.getComponent('tbh_tabs');
    if (!tc || !tc.getSelectedTabIndex) { return; }
    if (tc.getSelectedTabIndex() !== idx) { tc.setSelectedTabIndex(idx); }
    scwin.tbh_setLeaf(idx);
};

/**
 * @method
 * @name tbh_setLeaf
 * @description breadcrumb 리프 앵커(tbh_crumb_leaf)의 라벨을 i번째 탭 라벨(tbh_labels[i])로 설정한다.
 * @param {Number} i 선택 탭 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.tbh_setLeaf(0);
 */
scwin.tbh_setLeaf = function (i) {
    const a = $c.util.getComponent('tbh_crumb_leaf');
    if (a && a.setValue) { a.setValue(scwin.tbh_labels[i] || ''); }
};
